    return { prompt: "In a binomial tree for a call on a share priced at $" + S + ", u = " + u.toFixed(2) + " and d = 1/u. The values of the option at the upper and lower nodes after one step are $" + fu.toFixed(2) + " and $" + fd2.toFixed(2) + ". The estimate of delta is:", choices: strChoices(ans, [(fu - fd2) / S, (fu - fd2) / (Su - S), (fu + fd2) / (Su - Sd) / 2, 1 - ans], fmtD3), correct: 0 };
